package com.ricozknow.enterprise.metering; import com.ricozknow.common.TenantOwnedEntity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDate; @Entity @Table(name="usage_meters",uniqueConstraints=@UniqueConstraint(columnNames={"tenant_id","metric","period_start"})) @Getter @Setter @NoArgsConstructor public class UsageMeter extends TenantOwnedEntity { @Column(nullable=false) private String metric; @Column(name="period_start",nullable=false) private LocalDate periodStart; @Column(nullable=false,precision=20,scale=6) private BigDecimal quantity=BigDecimal.ZERO; }
